  legacy_word OP_XFER (bits8 a0 a1 a2 a3 a4 a5 a6 a7) (bits8 b0 b1 b2 b3 b4 b5 b6 b7) (bits8 c0 c1 c2 c3 c4 c5 c6 c7).
