Definition pdiscover_word (a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 : bool) : word InstrSz :=
  legacy_word OP_PDISCOVER (bits8 a0 a1 a2 a3 a4 a5 a6 a7) (bits8 b0 b1 b2 b3 b4 b5 b6 b7) (bits8 c0 c1 c2 c3 c4 c5 c6 c7).
Lemma step_pdiscover_pc : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b,
  step_fetched b = pdiscover_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 -> hwb_bianchi b = false ->
  hw_pc (step_next b) = if hw_nfi_ok (bits8 c0 c1 c2 c3 c4 c5 c6 c7) (bits8 b0 b1 b2 b3 b4 b5 b6 b7) then wplus (hw_pc b) (natToWord WordSz 1) else hw_trap_vector b.
Proof. hw_field. Qed.
Lemma step_pdiscover_mu : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b,
  step_fetched b = pdiscover_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 -> hwb_bianchi b = false ->
  hw_mu (step_next b) = if hw_nfi_ok (bits8 c0 c1 c2 c3 c4 c5 c6 c7) (bits8 b0 b1 b2 b3 b4 b5 b6 b7) then wplus (hw_mu b) (zext (bits8 c0 c1 c2 c3 c4 c5 c6 c7) 24) else hw_mu b.
Proof. hw_field. Qed.
Lemma step_pdiscover_err : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b,
  step_fetched b = pdiscover_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 -> hwb_bianchi b = false ->
  hw_err (step_next b) = if hw_nfi_ok (bits8 c0 c1 c2 c3 c4 c5 c6 c7) (bits8 b0 b1 b2 b3 b4 b5 b6 b7) then false else true.
Proof. hw_field. Qed.
Lemma step_pdiscover_halted : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b,
  step_fetched b = pdiscover_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 -> hwb_bianchi b = false ->
