Lemma step_load_regs : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b,
  step_fetched b = load_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 -> hwb_bianchi b = false ->
  hw_regs (step_next b) = if hw_region_ok b (split1 7 25 (hw_regs b (bits4 b0 b1 b2 b3))) then (fun w => if weq w ((bits4 a0 a1 a2 a3)) then hw_mem b (split1 7 25 (hw_regs b (bits4 b0 b1 b2 b3))) else hw_regs b w) else hw_regs b.
Proof. hw_field. Qed.
